def _pairs(pairs):
    data={}
    for key,value in pairs:
        if key in data:raise ValueError('Duplicate bundle key.')
        data[key]=value
    return data

def bounded_resource(path,digest):
    with path.open('rb') as stream:raw=stream.read(65537)
    if len(raw)>65536 or hashlib.sha256(raw).hexdigest()!=digest:raise ValueError('Unapproved/oversized context resource.')
    data=json.loads(raw,object_pairs_hook=_pairs,parse_constant=lambda _: (_ for _ in ()).throw(ValueError('Non-finite resource.')))
    pending=[(data,0)];count=0
    while pending:
        node,depth=pending.pop();count+=1
        if depth>12 or count>8192:raise ValueError('Unbounded context resource.')
        children=node.values() if type(node) is dict else node if type(node) is list else ()
        pending.extend((child,depth+1) for child in children)
    return data

@dataclass(frozen=True)
class ContextBundle:
    identifier:str
    manifest_sha256:str
    wave:str
    resources:tuple

    @classmethod
    def load(cls,identifier=EXPANDED):
        if identifier!=EXPANDED:raise ValueError('Unknown expanded context bundle.')
        record=ARCHIVES[ACTIVE_WAVE]
        manifest=bounded_resource(APP/'application/recommendation/config/context_expansion_bundle.v1.json',record['manifest_sha256'])
        if (set(manifest)!={'version','id','wave','default_activation','resources','active_situations','relative_situations','independent_validation'}
            or manifest['version']!='context-expansion-bundle-1.0.0' or manifest['id']!=EXPANDED or manifest['wave']!=ACTIVE_WAVE
            or manifest['default_activation'] is not False or manifest['resources']!=record['resources']
            or set(manifest['active_situations'])!=set(record['scopes']) or set(manifest['relative_situations'])!=set(record['targets'])
            or len(manifest['active_situations'])>32 or len(manifest['relative_situations'])>15 or manifest['independent_validation']!='OPEN'):
            raise ValueError('Unapproved context bundle manifest.')
        for name,digest in record['resources'].items():bounded_resource(APP/name,digest)
        return cls(EXPANDED,record['manifest_sha256'],ACTIVE_WAVE,tuple(sorted(record['resources'].items())))

    @property
    def record(self):return ARCHIVES[self.wave]

    def read(self,name):
        digest=dict(self.resources).get(name)
        if digest is None:raise ValueError('Unknown context resource name.')
        return bounded_resource(APP/name,digest)

def bundle_for_request(request):
    return getattr(getattr(request,'context',None),'bundle_id',LEGACY)

def archived_record(policy_version,policy_hash,catalogue_version,catalogue_hash,bundle_hash=None):
    for record in ARCHIVES.values():
        resources=record['resources']
        if (bundle_hash is None or bundle_hash==record['manifest_sha256']) and (policy_version,policy_hash,catalogue_version,catalogue_hash)==(record['policy_version'],resources['application/recommendation/config/context_relevance_policy.v2.json'],record['catalogue_version'],resources['application/recommendation/config/context_relevance_objectives.v2.json']):return record
    return None
